import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {createHash} from 'node:crypto';
import {pathToFileURL} from 'node:url';
const base='/Users/me/workspace/estate/estate-49f845d0dece/recallweave-trace-archive';
const files=['src/trace-archive.mjs','src/trace-archive-ui.mjs','src/app.mjs','tests/trace-archive.test.mjs'];
const pins=Object.fromEntries(files.map(file=>[file,createHash('sha256').update(readFileSync(base+'/'+file)).digest('hex')]));
console.log(JSON.stringify({receiver:'independent-controller-boundaries',node:process.version,pins}));
const {mountTraceArchive}=await import(pathToFileURL(base+'/src/trace-archive-ui.mjs'));
const {createTraceArchive}=await import(pathToFileURL(base+'/src/trace-archive.mjs'));
const {initialMastery,selectNextItem,updateMastery}=await import(pathToFileURL(base+'/src/knowledge.mjs'));
const deck=JSON.parse(readFileSync(base+'/data/deck.json','utf8'));
const blank=()=>({answers:[],mastery:initialMastery(deck.concepts),practice:null});
function completed(correct) {
  const state=blank(),asked=new Set();
  while(asked.size<deck.items.length){
    const item=selectNextItem(deck.items,asked,state.mastery);
    const choice=correct?item.answer:(item.answer+1)%item.options.length;
    state.answers.push({item:item.id,concept:item.concept,choice,correct});
    state.mastery[item.concept]=updateMastery(state.mastery[item.concept],correct);
    asked.add(item.id);
  }
  return state;
}
function mount(current) {
  const nodes=new Map();
  const query=selector=>{
    if(!nodes.has(selector))nodes.set(selector,{hidden:false,files:[],value:'',textContent:'',handlers:{},addEventListener(type,handler){this.handlers[type]=handler;},focus(){}});
    return nodes.get(selector);
  };
  const restored=[];
  mountTraceArchive({container:{innerHTML:'',querySelector:query},getDeck:()=>deck,getTrace:()=>current.state,restoreTrace:state=>{restored.push(state);current.state={answers:state.answers,mastery:state.mastery,practice:state.practice};}});
  return {query,restored};
}
const savedAt='2026-10-08T10:00:00.000Z';
const archiveA=createTraceArchive({deck,...completed(false),savedAt}).text;
const archiveB=createTraceArchive({deck,...completed(true),savedAt}).text;
{
  const current={state:blank()},ui=mount(current);
  const input=ui.query('#trace-file');
  let resolveOlder;
  const olderText=new Promise(resolve=>{resolveOlder=resolve;});
  input.files=[{size:Buffer.byteLength(archiveA),text:()=>olderText}];
  const older=input.handlers.change();
  input.files=[{size:Buffer.byteLength(archiveB),text:async()=>archiveB}];
  await input.handlers.change();
  const newerPreview=ui.query('#trace-preview-summary').textContent;
  assert.match(newerPreview,/First try: 6 of 6/);
  assert.equal(ui.restored.length,0);
  resolveOlder(archiveA);
  await older;
  assert.equal(ui.query('#trace-preview-summary').textContent,newerPreview);
  assert.equal(ui.restored.length,0);
  ui.query('#restore-trace-confirm').handlers.click();
  assert.equal(ui.restored.length,1);
  assert.deepEqual(ui.restored[0].answers,completed(true).answers);
  ui.query('#restore-trace-confirm').handlers.click();
  assert.equal(ui.restored.length,1);
  console.log(JSON.stringify({test:'older-read-cannot-replace-newer-preview',passed:true,previewDidNotMutateCurrentLesson:true,confirmedNewerAnswersOnly:true,repeatConfirmationDidNotRestoreAgain:true}));
}
